head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page,
body#layout .sidebar_top,
body#layout .sidebar_bottom {
  display: inline-block;
  left: inherit;
  position: relative;
  vertical-align: top;
}
body#layout .page {
  float: right;
  margin-left: 20px;
  width: 55%;
}
body#layout .sidebar-container {
  float: right;
  width: 40%;
}
body#layout .hamburger-menu {
  display: none;
}

div.script:
//

        // ==========================================
        // A. FUNGSI UTILITAS & FETCH DATA
        // ==========================================
        const APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbw9bbU21fKlYSDUz9dgc_6zwJ2RHLURQmDNZd5KXmfdet_0V7XKnMnUTmbM0iJPF9wB/exec';

        async function fetchAllData() {
            try { const r = await fetch(APPS_SCRIPT_URL + '?tab=ALL'); return await r.json(); }
            catch(e) { console.error('Gagal memuat data:', e); return null; }
        }

        function img(foto, w, h) {
            if (!foto) return '';
            foto = String(foto).trim();

            // Deteksi otomatis jika link berasal dari Google Drive (format biasa)
            const driveRegex = /drive\.google\.com\/file\/d\/([^\/]+)/;
            const match = foto.match(driveRegex);

            if (match && match[1]) {
                // Menggunakan server lh3.googleusercontent.com yang tahan blokir untuk embed gambar
                return 'https://lh3.googleusercontent.com/d/' + match[1];
            }

            // Jika sudah berupa link langsung berawalan http (selain Drive format lama), biarkan
            if (foto.startsWith('http')) return foto;

            // Default untuk ID Unsplash (jika hanya memasukkan kode singkat)
            return 'https://images.unsplash.com/photo-' + foto + '?w=' + w + '&h=' + h + '&fit=crop&auto=format';
        }

        // FUNGSI arrToObj YANG SUDAH DIPERBAIKI (bisa baca Array maupun Object)
        const arrToObj = (input) => {
            if (!input) return {};
            // Jika sudah berupa object biasa, langsung return
            if (typeof input === 'object' && !Array.isArray(input)) {
                return input;
            }
            // Jika berupa array of {Key, Value}, konversi ke object
            if (Array.isArray(input)) {
                return input.reduce((acc, curr) => {
                    acc[curr.Key] = curr.Value;
                    return acc;
                }, {});
            }
            return {};
        };

        function toggleMenu() {
            const nav = document.getElementById('mobileNav');
            const overlay = document.getElementById('mobileOverlay');
            if(nav) nav.classList.toggle('active');
            if(overlay) overlay.classList.toggle('active');
        }


        // ==========================================
        // B. VARIABEL GLOBAL HALAMAN SPESIFIK
        // ==========================================
        let globalWisataData = [];
        let currentPage = 1;
        const PER_PAGE = 6;

        let globalProdukData = [];
        let currentProdukPage = 1;


        // ==========================================
        // C. RENDERER UTAMA (MASTER RENDER) - SEMUA KEY SUDAH DIPERBAIKI
        // ==========================================
        async function renderData() {
            const data = await fetchAllData();
            if (!data) return;

            // 1. RENDER BERANDA
            if (document.getElementById('hero-bg')) {
                const b = arrToObj(data['beranda'] || data['Beranda']);
                if (b.HeroFoto) {
                    document.getElementById('hero-bg').style.backgroundImage = `url('${img(b.HeroFoto, 1600, 900)}')`;
                    const heroImg = document.getElementById('hero-img');
                    if (heroImg) {
                        heroImg.src = img(b.HeroFoto, 1600, 600);
                        heroImg.alt = b.HeroJudul1 || '';
                    }
                }
                if (b.HeroJudul1 || b.HeroJudul2) document.getElementById('hero-title').innerHTML = (b.HeroJudul1 || '') + ' <span>' + (b.HeroJudul2 || '') + '</span>';
                if (b.HeroSubtitle) document.getElementById('hero-subtitle').textContent = b.HeroSubtitle;
                document.querySelector('.hero-content').classList.add('loaded');

                const fakta = data['fakta-cepat'] || data['FaktaCepat'] || [];
                if (fakta.length > 0) {
                    const fcEl = document.getElementById('fakta-cepat');
                    if(fcEl) fcEl.innerHTML = fakta.map(f => `
                        <div class="fakta-item">
                            <span class="fakta-value">${f.Value || ''}</span>
                            <span class="fakta-unit">${f.Unit || ''}</span>
                            <span class="fakta-label">${f.Label || ''}</span>
                        </div>
                    `).join('');
                }

                // Beranda Wisata Slider
                const wisata = data['wisata'] || data['Wisata'] || [];
                if (wisata.length > 0) {
                    const featured = wisata.find(w => String(w.Featured || '').toLowerCase() === 'ya');
                    if (featured) {
                        const tEl = document.getElementById('fw-title'); if(tEl) tEl.textContent = featured.Nama || '';
                        const dEl = document.getElementById('fw-desc'); if(dEl) dEl.textContent = featured.Deskripsi || '';
                        const ft = featured.FotoGaleri || featured.Foto || '';
                        const fotoList = ft ? ft.split(',').map(s => s.trim()) : [];
                        if (fotoList.length > 0) {
                            const imgContainer = document.getElementById('fw-main-img-container');
                            if(imgContainer) imgContainer.innerHTML = `<img src="${img(fotoList[0], 800, 400)}" alt="${featured.Nama}" class="card-featured-main-img">`;
                            const galleryEl = document.getElementById('fw-gallery');
                            if(galleryEl && fotoList.length > 1) {
                                galleryEl.innerHTML = fotoList.slice(1, 4).map(url =>
                                    `<img src="${img(url, 500, 248)}" alt="${featured.Nama}" class="card-featured-gallery-img">`
                                ).join('');
                            }
                        }
                    }
                    const slider = document.getElementById('wisata-slider');
                    if(slider) {
                        slider.innerHTML = wisata.filter(w => w.StatusPublikasi === 'Publikasikan').map(w => {
                            const ft = w.Foto ? w.Foto.split(',')[0].trim() : '';
                            return `
                            <div class="card wisata-card">
                                <img src="${img(ft, 635, 314)}" alt="${w.Nama}">
                                <div class="wisata-card-content">
                                    <h4 class="wisata-card-title">${w.Nama}</h4>
                                    <div class="wisata-card-loc"><span>${w.Lokasi || w.Jarak || ''}</span></div>
                                </div>
                            </div>`;
                        }).join('');
                    }
                }

                // Beranda Produk Preview
                const produk = data['produk'] || data['Produk'] || [];
                if (produk.length > 0) {
                    const previewProd = document.getElementById('produk-preview');
                    if(previewProd) {
                        previewProd.innerHTML = produk.slice(0, 4).map(p => {
                            const ft = p.Foto ? p.Foto.split(',')[0].trim() : '';
                            const price = (p.Harga || '').split(' / ')[0];
                            return `
                            <div class="card product-card">
                                <div class="card-img-wrap"><img src="${img(ft, 500, 500)}" alt="${p.Nama}" class="card-img"></div>
                                <div class="card-content">
                                    <span class="seller-name">${p.Penjual || ''}</span>
                                    <h4 class="product-name">${p.Nama}</h4>
                                    <div class="price-wrap"><div class="price">${price}</div></div>
                                </div>
                            </div>`;
                        }).join('');
                    }
                }
            } // END BERANDA


            // 2. RENDER PROFIL DESA
            if (document.getElementById('demografi-container')) {
                // Render Sejarah Desa
                const sejarahData = arrToObj(data['sejarah'] || data['Sejarah']);
                if (Object.keys(sejarahData).length !== 0) {
                    const elJudul = document.getElementById('sejarah-judul');
                    if (elJudul && sejarahData.SejarahJudul) elJudul.textContent = sejarahData.SejarahJudul;

                    const elTeks = document.getElementById('sejarah-teks');
                    if (elTeks) {
                        let teksHtml = '';
                        if (sejarahData.SejarahParagraf1) teksHtml += `<p>${sejarahData.SejarahParagraf1}</p>`;
                        if (sejarahData.SejarahParagraf2) teksHtml += `<p>${sejarahData.SejarahParagraf2}</p>`;
                        if (sejarahData.SejarahParagraf3) teksHtml += `<p>${sejarahData.SejarahParagraf3}</p>`;
                        if (sejarahData.SejarahParagraf4) teksHtml += `<p>${sejarahData.SejarahParagraf4}</p>`;
                        elTeks.innerHTML = teksHtml || '<p>Data sejarah belum tersedia.</p>';
                    }

                    const elFoto = document.getElementById('sejarah-foto');
                    const elFotoSkel = document.getElementById('sejarah-foto-skeleton');
                    if (elFoto && sejarahData.SejarahFoto) {
                        elFoto.src = img(sejarahData.SejarahFoto, 800, 600);
                        elFoto.style.display = 'block';
                        if (elFotoSkel) elFotoSkel.style.display = 'none';
                    }
                }

                const rawDemo = data['data-desa'] || data['DataDesa'] || {};
                let demo = [];
                if (Array.isArray(rawDemo)) {
                    // Jika data berupa Array, saring baris header
                    demo = rawDemo.filter(c => c.Key && c.Key.toLowerCase() !== 'key');
                } else {
                    // Jika data berupa Object, saring kunci bernama "Key", lalu ubah ke Array
                    demo = Object.entries(rawDemo)
                        .filter(([key, value]) => key.toLowerCase() !== 'key') 
                        .map(([key, value]) => ({ Key: key, Value: value, Satuan: '' }));
                }

                if (demo.length > 0) {
                    document.getElementById('demografi-container').innerHTML = demo.map(c => `
                        <div class="card stat-card" style="color: var(--accent-gold);">
                            <div class="stat-value">${c.Value || ''}<span class="stat-unit">${c.Satuan || ''}</span></div>
                            <div class="stat-label">${c.Key || ''}</div>
                        </div>`).join('');
                }

                const potensi = data['potensi-desa'] || data['PotensiDesa'] || [];
                if(potensi.length > 0) {
                    document.getElementById('potensi-container').innerHTML = potensi.map(p => `
                    <div class="card potensi-card">
                        <span class="potensi-icon">${p.Ikon || '📍'}</span>
                        <h4 class="potensi-title">${p.Judul || ''}</h4>
                        <p class="potensi-desc">${p.Deskripsi || ''}</p>
                    </div>`).join('');
                }

                const visiMisi = data['visi-misi'] || data['VisiMisi'] || [];
                if(visiMisi.length > 0) {
                    let visi = visiMisi.filter(v => String(v.Tipe).toLowerCase() === 'visi').sort((a,b) => a.Urutan - b.Urutan).map(v => v.Isi).join(' ');
                    let misi = visiMisi.filter(v => String(v.Tipe).toLowerCase() === 'misi').sort((a,b) => a.Urutan - b.Urutan);
                    document.getElementById('visi-text').textContent = visi;
                    document.getElementById('misi-list').innerHTML = misi.map((m, i) => `
                    <li class="misi-item">
                        <span class="misi-number">${i+1}</span><p style="margin:0;">${m.Isi || ''}</p>
                    </li>`).join('');
                }

                const orgsData = data['perangkat-desa'] || data['PerangkatDesa'] || [];
                if(orgsData.length > 0) {
                    let orgs = orgsData.sort((a,b) => a.Urutan - b.Urutan);
                    document.getElementById('struktur-container').innerHTML = orgs.map(p => `
                    <div class="card struktur-card">
                        <img src="${img(p.Foto, 112, 112)}" alt="${p.Nama}" class="struktur-photo">
                        <h4 class="struktur-name">${p.Nama || ''}</h4>
                        <span class="struktur-role">${p.Jabatan || ''}</span>
                    </div>`).join('');
                }
            } // END PROFIL DESA


            // 3. RENDER WISATA
            if (document.getElementById('wisata-grid')) {
                const wisataData = data['wisata'] || data['Wisata'];
                if(wisataData) {
                    globalWisataData = wisataData;
                    renderWisataPagination(); 
                } else {
                    document.getElementById('wisata-grid').innerHTML = '<p style="grid-column: 1/-1; text-align: center; padding: 40px;">Data wisata belum tersedia.</p>';
                }
            }


            // 4. RENDER PRODUK LOKAL
            if (document.getElementById('product-grid')) {
                const produkData = data['produk'] || data['Produk'];
                if(produkData) {
                    globalProdukData = produkData;
                    renderProdukPagination();
                } else {
                    document.getElementById('product-grid').innerHTML = '<p style="grid-column: 1/-1; text-align: center; padding: 40px;">Data produk belum tersedia.</p>';
                }
            }


            // 5. RENDER PETA & EVAKUASI
            if (document.getElementById('content-peta')) {
                const pbObj = arrToObj(data['peta-bencana'] || data['PetaBencana']);
                if (Object.keys(pbObj).length !== 0) {
                    const banner = document.getElementById('banner-title');
                    if(banner) banner.innerHTML = `${pbObj.JumlahTerdampak || '0'} dari ${pbObj.TotalPenduduk || '0'} ${pbObj.Keterangan || ''}`;
                }

                const dusun = data['dusun'] || data['Dusun'] || [];
                if (dusun.length > 0) {
                    document.getElementById('content-peta').innerHTML = dusun.map(item => `
                        <div class="card dusun-card" onclick="zoomToDusun('${item.Nama || ''}')" style="cursor: pointer;">
                            <div class="dusun-icon"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg></div>
                            <div class="dusun-info">
                                <h4>${item.Nama || '-'}</h4>
                                <p>${item.Keterangan || '-'}</p>
                            </div>
                        </div>
                    `).join('');
                }

                const darurat = data['kontak-darurat'] || data['KontakDarurat'] || [];
                if (darurat.length > 0) {
                    document.getElementById('darurat-list').innerHTML = darurat.map(item => `
                        <div class="darurat-contact-card">
                            <span class="contact-emoji">${item.Ikon || '☎️'}</span>
                            <div class="contact-info">
                                <h4>${item.Label || '-'}</h4>
                                <div class="contact-number">${item.Nomor || '-'}</div>
                            </div>
                        </div>
                    `).join('');
                }
            } // END PETA


            // 6. RENDER BERITA (Dari Feed Blogger)
            if (document.getElementById('news-list-container')) {
                // Berita sekarang dimuat langsung dari Blogger JSON Feed di Berita.html
            }

            // BERITA PREVIEW DI BERANDA (dari Blogger Feed)
            if (document.getElementById('berita-preview-container')) {
                try {
                    const feedResp = await fetch('/feeds/posts/default?alt=json&max-results=3');
                    const feedData = await feedResp.json();
                    const entries = feedData.feed.entry || [];
                    if (entries.length > 0) {
                        document.getElementById('berita-preview-container').innerHTML = entries.map(entry => {
                            const title = entry.title.$t || '';
                            const published = new Date(entry.published.$t).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
                            const content = entry.content ? entry.content.$t : (entry.summary ? entry.summary.$t : '');
                            const snippet = content.replace(/<[^>]*>/g, '').substring(0, 150) + '...';
                            let thumbnail = '';
                            if (entry.media$thumbnail) { thumbnail = entry.media$thumbnail.url.replace('/s72-c/', '/s600/'); }
                            else { const imgMatch = content.match(/<img[^>]+src=["']([^"']+)/); if (imgMatch) thumbnail = imgMatch[1]; }
                            const labels = entry.category ? entry.category.map(c => c.term) : [];
                            const cat = labels.includes('Pemberitahuan') ? 'Pemberitahuan' : 'Umum';
                            const badgeClass = cat === 'Pemberitahuan' ? 'badge-pemberitahuan' : 'badge-umum';
                            const postUrl = entry.link ? entry.link.find(l => l.rel === 'alternate')?.href || '/p/berita.html' : '/p/berita.html';
                            return `
                            <a class="card berita-card" href="/p/berita.html">
                                ${thumbnail ? `<img alt="${title}" class="berita-img" src="${thumbnail}"/>` : `<div class="berita-img" style="background:var(--bg-tertiary);display:flex;align-items:center;justify-content:center;color:var(--text-muted);">📰</div>`}
                                <div class="berita-content">
                                    <span class="berita-badge ${badgeClass}">${cat}</span>
                                    <h3 class="berita-title">${title}</h3>
                                    <p class="berita-snippet">${snippet}</p>
                                    <div class="berita-date">${published}</div>
                                </div>
                            </a>`;
                        }).join('');
                    }
                } catch(e) { console.log('Berita preview gagal dimuat:', e); }
            }

            // 7. RENDER KONTAK HALAMAN & FOOTER
            const k = arrToObj(data['kontak'] || data['Kontak']);
            if (Object.keys(k).length !== 0) {
                // Di Halaman Kontak
                if(document.getElementById('kontak-alamat')) {
                    if(k.Alamat) document.getElementById('kontak-alamat').textContent = k.Alamat;
                    if(k.Telepon) document.getElementById('kontak-telepon').textContent = k.Telepon;
                    if(k.Email) document.getElementById('kontak-email').textContent = k.Email;
                    if(k.JamSenJum) {
                        const el = document.getElementById('kontak-jam-senjum');
                        el.textContent = k.JamSenJum;
                        el.classList.remove('skeleton', 'skeleton-text'); 
                        el.removeAttribute('style'); // Menghapus batasan kotak 80px agar teks bebas memanjang
                    }
                    if(k.JamSabtu) {
                        const el = document.getElementById('kontak-jam-sabtu');
                        el.textContent = k.JamSabtu;
                        el.classList.remove('skeleton', 'skeleton-text'); 
                        el.removeAttribute('style'); // Menghapus batasan kotak 80px agar teks bebas memanjang
                    }
                    if(k.WhatsApp) { const el = document.getElementById('wa-btn'); if(el) el.href = 'https://wa.me/' + k.WhatsApp; }
                    if(k.Facebook) { const el = document.getElementById('sosmed-fb-link'); if(el) el.href = k.Facebook; }
                    if(k.FacebookLabel) { const el = document.getElementById('sosmed-fb-label'); if(el) el.textContent = k.FacebookLabel; }
                    if(k.Instagram) { const el = document.getElementById('sosmed-ig-link'); if(el) el.href = k.Instagram; }
                    if(k.InstagramLabel) { const el = document.getElementById('sosmed-ig-label'); if(el) el.textContent = k.InstagramLabel; }
                }

                // Header logo (dari HeaderLogo, atau fallback FooterLogo)
                const headerLogoSrc = k.HeaderLogo || k.FooterLogo || '';
                if (headerLogoSrc) { const el = document.getElementById('header-logo-img'); if(el) el.src = img(headerLogoSrc, 400, 400); }

                // Di Footer Global (Mencakup seluruh bagian sesuai foto)
                if (k.FooterLogo) { const el = document.getElementById('footer-logo-img'); if(el) el.src = img(k.FooterLogo, 500, 150); }
                if (k.FooterNamaDesa) { const el = document.getElementById('footer-nama-desa'); if(el) el.textContent = k.FooterNamaDesa; }
                if (k.FooterSubDesa) { const el = document.getElementById('footer-sub-desa'); if(el) el.textContent = k.FooterSubDesa; }
                if (k.FooterDeskripsi) { const el = document.getElementById('footer-deskripsi'); if(el) el.textContent = k.FooterDeskripsi; }
                if (k.Alamat) { const el = document.getElementById('footer-alamat'); if(el) el.textContent = k.Alamat; }
                if (k.Telepon) { const el = document.getElementById('footer-telepon'); if(el) el.textContent = k.Telepon; }
                if (k.Email) { const el = document.getElementById('footer-email'); if(el) el.textContent = k.Email; }
                if (k.JamSenJum) { const el = document.getElementById('footer-jam-senjum'); if(el) el.textContent = 'Senin – Jumat: ' + k.JamSenJum; }
                if (k.JamSabtu) { const el = document.getElementById('footer-jam-sabtu'); if(el) el.textContent = 'Sabtu: ' + k.JamSabtu; }
                if (k.Facebook) { const el = document.getElementById('footer-fb'); if(el) el.href = k.Facebook; }
                if (k.Instagram) { const el = document.getElementById('footer-ig'); if(el) el.href = k.Instagram; }
            }
        }
        // ==========================================
        // D. FUNGSI LOGIKA HALAMAN (ONCLICK)
        // ==========================================

        // --- Wisata ---
        window.renderWisataPagination = function() {
            const grid = document.getElementById('wisata-grid');
            if(!grid) return;
            const totalPages = Math.ceil(globalWisataData.length / PER_PAGE);
            const startIndex = (currentPage - 1) * PER_PAGE;
            const currentItems = globalWisataData.slice(startIndex, startIndex + PER_PAGE);

            grid.innerHTML = currentItems.map((item, index) => {
                const dataIndex = startIndex + index;
                const descLen = (item.Deskripsi || '').length;
                const isTopPick = ['ya','true','1'].includes(String(item.Featured || '').toLowerCase().trim());
                const pattern = ['hero', 'default', 'default', 'wide', 'tall', 'default'];
                let size = pattern[dataIndex % 6];
                if (size === 'hero' && descLen < 150 && !isTopPick) { size = 'default'; }
                if (size === 'wide' && descLen < 80) { size = 'default'; }
                if (size === 'tall' && descLen < 100) { size = 'default'; }
                if (isTopPick) { size = 'hero'; }
                const imgDims = { hero: [1280, 800], wide: [900, 500], tall: [800, 907], default: [800, 640] };
                const [rw, rh] = imgDims[size] || imgDims.default;
                const src = item.Foto || (item.FotoGaleri ? item.FotoGaleri.split(',')[0] : '');
                const gallery = item.FotoGaleri ? item.FotoGaleri.split(',').filter(f => f.trim()) : [];
                const galleryThumbs = gallery.slice(gallery[0] === src ? 1 : 0, 4);
                const isFeaturedCard = isTopPick && galleryThumbs.length >= 3;
                return `
                  <div class="card wisata-card ${isFeaturedCard ? 'wisata-featured' : ''}" data-size="${size}" data-index="${dataIndex}" onclick="openModal(${dataIndex})">
                 <div class="card-img-wrap"><img src="${img(src, rw, rh)}" alt="${item.Nama}" class="card-img" loading="lazy"></div>
                 ${isFeaturedCard ? `
                 <div class="featured-thumbs">
                     ${galleryThumbs.map(url => `<img src="${img(url, 300, 200)}" alt="${item.Nama}" loading="lazy">`).join('')}
                 </div>` : ''}
                 <div class="card-content">
                     ${isTopPick ? '<span class="top-pick-badge">⭐ Rekomendasi</span>' : ''}
                     <h3 class="card-title">${item.Nama}</h3>
                     <div class="card-location"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg>${item.Lokasi}</div>
                     <p class="card-desc">${item.Deskripsi || ''}</p>
                 </div>
                 </div>`
            }).join('');

            let controls = document.getElementById('pagination-controls');
            if (!controls) {
                controls = document.createElement('div'); controls.id = 'pagination-controls'; controls.className = 'pagination';
                grid.parentNode.appendChild(controls);
            }
            let pagHtml = '';
            if (totalPages > 1) {
                pagHtml += `<button class="page-btn" onclick="goToPage(${currentPage - 1})" ${currentPage === 1 ? 'disabled' : ''}>Prev</button>`;
                for (let i = 1; i <= totalPages; i++) pagHtml += `<button class="page-btn ${currentPage === i ? 'active' : ''}" onclick="goToPage(${i})">${i}</button>`;
                pagHtml += `<button class="page-btn" onclick="goToPage(${currentPage + 1})" ${currentPage === totalPages ? 'disabled' : ''}>Next</button>`;
            }
            controls.innerHTML = pagHtml;
        };

        window.goToPage = function(page) {
            const totalPages = Math.ceil(globalWisataData.length / PER_PAGE);
            if (page >= 1 && page <= totalPages) { currentPage = page; renderWisataPagination(); document.querySelector('.page-header').scrollIntoView({ behavior: 'smooth' }); }
        };

        window.openModal = function(index) {
            const item = globalWisataData[index]; const modalOverlay = document.getElementById('modal-overlay');
             if(!item || !modalOverlay) return;
             const gallery = item.FotoGaleri ? item.FotoGaleri.split(',').filter(f => f.trim()) : [];
             document.getElementById('modal-img').src = img(item.Foto || (gallery[0] || ''), 800, 450);
             document.getElementById('modal-category').innerText = item.Kategori || '-';
             document.getElementById('modal-title').innerText = item.Nama || '-';
             document.getElementById('modal-loc-text').innerText = item.Lokasi || '-';
             document.getElementById('modal-desc').innerText = item.Deskripsi || '-';
             document.getElementById('modal-hours').innerText = item.JamOperasional || '-';
             document.getElementById('modal-price').innerText = item.HargaTiket || '-';
             document.getElementById('modal-coords').innerText = item.Koordinat || '-';

             // Top Pick badge
              const isTopPick = ['ya','true','1'].includes(String(item.Featured || '').toLowerCase().trim());
             const topPickBadge = document.getElementById('modal-top-pick');
             if(topPickBadge) topPickBadge.style.display = isTopPick ? 'inline-flex' : 'none';

              // Gallery thumbnails
              const thumbsContainer = document.getElementById('modal-thumbs');
              if(thumbsContainer) {
                  const mainIsFromGallery = !item.Foto && gallery.length > 0;
                  const thumbList = mainIsFromGallery ? gallery.slice(1, 7) : gallery.slice(0, 6);
                  if(thumbList.length > 0) {
                      thumbsContainer.innerHTML = thumbList.map(url =>
                          `<img src="${img(url, 100, 80)}" alt="Gallery photo" onclick="document.getElementById('modal-img').src='${img(url, 800, 450)}'">`
                      ).join('');
                      thumbsContainer.style.display = 'flex';
                  } else {
                      thumbsContainer.innerHTML = '';
                      thumbsContainer.style.display = 'none';
                  }
              }

             const mapLink = document.getElementById('modal-map-link');
            if (item.Koordinat) { mapLink.href = `https://www.google.com/maps?q=${item.Koordinat}`; mapLink.style.display = 'flex'; } 
            else { mapLink.style.display = 'none'; }
            modalOverlay.classList.add('active'); document.body.style.overflow = 'hidden';
        };

        window.closeModal = function() {
            const modalOverlay = document.getElementById('modal-overlay');
            if(modalOverlay) modalOverlay.classList.remove('active'); document.body.style.overflow = '';
        };

        window.handleOverlayClick = function(e) { const modalOverlay = document.getElementById('modal-overlay'); if(e.target === modalOverlay) closeModal(); };

        // --- Produk Lokal ---
        window.renderProdukPagination = function() {
            const grid = document.getElementById('product-grid');
            if(!grid) return;
            const totalPages = Math.ceil(globalProdukData.length / 6);
            const startIndex = (currentProdukPage - 1) * 6;
            const currentItems = globalProdukData.slice(startIndex, startIndex + 6);

            grid.innerHTML = currentItems.map(item => {
                const parts = (item.Harga || '').split(' / ');
                const price = parts[0]; const unit = parts.length > 1 ? '/ ' + parts.slice(1).join(' / ') : '';
                return `
                <div class="card product-card">
                  <div class="card-img-wrap"><img src="${img(item.Foto, 500, 500)}" alt="${item.Nama}" class="card-img" loading="lazy"></div>
                  <div class="card-content">
                    <div class="seller-name">${item.Penjual || '-'}</div>
                    <h3 class="product-name">${item.Nama || '-'}</h3>
                    <div class="price-wrap"><div class="price">${price} <span class="unit">${unit}</span></div></div>
                    <a href="${item.Link && item.Link !== '-' ? item.Link : '#'}" class="btn-buy" ${item.Link && item.Link !== '-' ? 'target="_blank" rel="noopener noreferrer"' : ''}>
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"/><path d="M3 6h18"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>Beli Sekarang
                    </a>
                  </div>
                </div>`
            }).join('');

            let controls = document.getElementById('produk-pagination-controls');
            if (!controls) {
                controls = document.createElement('div'); controls.id = 'produk-pagination-controls'; controls.className = 'pagination';
                grid.parentNode.appendChild(controls);
            }
            let pagHtml = '';
            if (totalPages > 1) {
                pagHtml += `<button class="page-btn" onclick="goToProdukPage(${currentProdukPage - 1})" ${currentProdukPage === 1 ? 'disabled' : ''}>Prev</button>`;
                for (let i = 1; i <= totalPages; i++) pagHtml += `<button class="page-btn ${currentProdukPage === i ? 'active' : ''}" onclick="goToProdukPage(${i})">${i}</button>`;
                pagHtml += `<button class="page-btn" onclick="goToProdukPage(${currentProdukPage + 1})" ${currentProdukPage === totalPages ? 'disabled' : ''}>Next</button>`;
            }
            controls.innerHTML = pagHtml;
        };

        window.goToProdukPage = function(page) {
            const totalPages = Math.ceil(globalProdukData.length / 6);
            if (page >= 1 && page <= totalPages) { currentProdukPage = page; renderProdukPagination(); document.querySelector('.page-header').scrollIntoView({ behavior: 'smooth' }); }
        };

       // --- Peta, Evakuasi & Leaflet ---
        let map = null;
        let mapLayers = {};
        let poiMarkers = [];

        window.filterKategori = function(kategori) {
            const isVisible = mapLayers.poiBangunan;
            poiMarkers.forEach(pm => {
                if (pm.kategori === kategori) {
                    if (pm.cb.checked) {
                        mapLayers.poiBangunan.addLayer(pm.marker);
                    } else {
                        mapLayers.poiBangunan.removeLayer(pm.marker);
                    }
                }
            });
        };

        window.checkAllKategori = function(state) {
            const cbs = document.querySelectorAll('.kategori-checkbox');
            cbs.forEach(cb => {
                cb.checked = state;
                filterKategori(cb.value);
            });
            const btn = document.getElementById('check-all-btn');
            if (btn) btn.textContent = state ? 'Kosongkan' : 'Cek Semua';
        };

        window.switchTab = function(tabId) {
            document.getElementById('btn-peta').classList.remove('active');
            document.getElementById('btn-evakuasi').classList.remove('active');
            document.getElementById('btn-' + tabId).classList.add('active');

            document.getElementById('content-peta').style.display = 'none';
            document.getElementById('content-evakuasi').style.display = 'none';
            document.getElementById('content-' + tabId).style.display = 'grid'; 

            const badge = document.getElementById('map-badge');
            const title = document.getElementById('map-title-text');
            if(badge) {
                if(tabId === 'peta') {
                    badge.innerHTML = '🗺️ Peta Desa';
                    badge.style.background = 'var(--accent-green-dim)';
                    badge.style.color = 'var(--accent-green)';
                    badge.style.borderColor = 'rgba(16, 185, 129, 0.3)';
                    if(title) title.innerText = 'Peta Wilayah Desa Kembang';
                } else {
                    badge.innerHTML = '🚨 Rute Evakuasi';
                    badge.style.background = 'var(--danger-dim)';
                    badge.style.color = 'var(--danger)';
                    badge.style.borderColor = 'rgba(248, 81, 73, 0.3)';
                    if(title) title.innerText = 'Peta Jalur Evakuasi';
                }
            }

            // Tukar visibility layer Landmark vs Evakuasi saat ganti tab
            if (map && mapLayers.poiBangunan && mapLayers.poiEvakuasi) {
                if (tabId === 'peta') {
                    map.addLayer(mapLayers.poiBangunan);
                    map.removeLayer(mapLayers.poiEvakuasi);
                } else {
                    map.removeLayer(mapLayers.poiBangunan);
                    map.addLayer(mapLayers.poiEvakuasi);
                }
            }
        };

        window.zoomToDusun = function(namaDusun) {
            if (!map || !mapLayers.dusun) return;

            // Otomatis pindah ke tab Peta jika sedang di tab Rute Evakuasi
            const btnPeta = document.getElementById('btn-peta');
            if (btnPeta && !btnPeta.classList.contains('active')) {
                window.switchTab('peta');
            }

            let found = false;
            let targetDusun = (namaDusun || '').toLowerCase().trim();
            let altDusun = targetDusun;

            // Penanganan khusus variasi penulisan Bubakan / Babakan
            if (targetDusun.includes('bubakan')) altDusun = targetDusun.replace('bubakan', 'babakan');
            if (targetDusun.includes('babakan')) altDusun = targetDusun.replace('babakan', 'bubakan');

            mapLayers.dusun.eachLayer(function(layer) {
                if (layer.feature && layer.feature.properties) {
                    const props = layer.feature.properties;
                    const namaGeojson = String(props.Name || props.name || props.NAMOBJ || props.nama_dusun || props.Dusun || props.dusun || '').toLowerCase();

                    if (namaGeojson && (namaGeojson.includes(targetDusun) || (altDusun && namaGeojson.includes(altDusun)))) {
                        map.fitBounds(layer.getBounds(), { padding: [30, 30] });
                        found = true;
                    }
                }
            });

            if (found) {
                const petaContainer = document.getElementById('map');
                if (petaContainer) petaContainer.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        };

        // Sungai dihapus dari daftar
        const GEOJSON_URLS = {
            dusun: 'https://raw.githubusercontent.com/Danial-AM/desa-kembang-assets/refs/heads/main/Batas%20Dusun%20Kembang.geojson',
            road: 'https://raw.githubusercontent.com/Danial-AM/desa-kembang-assets/refs/heads/main/Jalan%20Desa%20Kembang.geojson',
            evacRoute: 'https://raw.githubusercontent.com/Danial-AM/desa-kembang-assets/refs/heads/main/Arah%20Evakuasi.geojson'
        };

        const ICON_CONFIG = {
            'Ibadah': { color: '#10b981', icon: '🕌' },
            'Pendidikan': { color: '#f59e0b', icon: '🏫' },
            'Pemerintahan': { color: '#3b82f6', icon: '🏛️' },
            'Kesehatan': { color: '#ef4444', icon: '🏥' },
            'Fasilitas Umum': { color: '#8b5cf6', icon: '🏢' },
            'Infrastruktur': { color: '#6b7280', icon: '🛠️' },
            'Wisata': { color: '#14b8a6', icon: '🏖️' },
            'Evakuasi': { color: '#f43f5e', icon: '🚨' },
            'Default': { color: '#eab308', icon: '📌' }
        };

        function getCustomIcon(kategori, isEvakuasi = false) {
            const config = isEvakuasi ? ICON_CONFIG['Evakuasi'] : (ICON_CONFIG[kategori] || ICON_CONFIG['Default']);
            return L.divIcon({
                html: `<div style="width: 28px; height: 28px; background-color: ${config.color}; border-radius: 50%; border: 2px solid #fff; box-shadow: 0 0 8px ${config.color}; display: flex; align-items: center; justify-content: center; font-size: 14px; color: white;">${config.icon}</div>`,
                className: 'custom-poi-icon',
                iconSize: [32, 32],
                iconAnchor: [16, 16],
                popupAnchor: [0, -16]
            });
        }

        window.initMap = async function() {
            const mapEl = document.getElementById('map');
            const loadingEl = document.getElementById('map-loading');
            if (!mapEl || !loadingEl || map !== null) return;  

            loadingEl.style.display = 'flex';
            mapEl.style.display = 'none';

            // Memuat Leaflet + Plugin PolylineDecorator (untuk Panah)
            if (!document.querySelector('#leaflet-css')) {
                const css = document.createElement('link'); css.id = 'leaflet-css'; css.rel = 'stylesheet'; css.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css'; document.head.appendChild(css);

                const js = document.createElement('script'); js.id = 'leaflet-js'; js.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
                js.onload = () => {
                    const jsDeco = document.createElement('script');
                    jsDeco.src = 'https://unpkg.com/leaflet-polylinedecorator@1.6.0/dist/leaflet.polylineDecorator.js';
                    jsDeco.onload = () => setupMap();
                    document.head.appendChild(jsDeco);
                };
                document.head.appendChild(js);
            } else if (window.L && window.L.polylineDecorator) {
                setupMap();
            }
        };

       async function setupMap() {
            map = L.map('map').setView([-8.213, 111.11], 15);
            L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', { attribution: '© OSM © CARTO', maxZoom: 19 }).addTo(map);

            mapLayers = {
                dusun: L.geoJSON(null, { style: { color: '#10b981', weight: 2, fillColor: 'rgba(16, 185, 129, 0.05)', fillOpacity: 0.2 } }).addTo(map),
                road: L.geoJSON(null, { style: { color: '#6b7280', weight: 2, opacity: 0.7 } }).addTo(map),
                evacRoute: L.featureGroup().addTo(map),
                poiBangunan: L.featureGroup().addTo(map),
                poiEvakuasi: L.featureGroup()
            };

            L.control.layers(
                null, 
                {
                    'Batas Dusun': mapLayers.dusun,
                    'Jalan Desa': mapLayers.road,
                    'Rute Evakuasi': mapLayers.evacRoute,
                    'Landmark & Fasilitas': mapLayers.poiBangunan,
                    'Titik Evakuasi': mapLayers.poiEvakuasi
                },
                { collapsed: false, position: 'topright' }
            ).addTo(map);

            document.getElementById('map-loading').style.display = 'none';
            document.getElementById('map').style.display = 'block';
            setTimeout(() => map.invalidateSize(), 300);

            // 1. Fetch Garis & Area dari GitHub (Dengan Pengaman PolylineDecorator)
            await Promise.allSettled(Object.entries(GEOJSON_URLS).map(async ([key, url]) => {
                try {
                    const data = await fetch(url).then(r => r.json());
                    if (data) {
                        if (key === 'evacRoute') {
                            // Memasang Panah pada masing-masing segmen rute dengan aman
                            const routeLayer = L.geoJSON(data, { 
                                style: { color: '#ef4444', weight: 4, opacity: 0.8, dashArray: '5, 8' },
                                onEachFeature: function(feature, layer) {
                                    L.polylineDecorator(layer, {
                                        patterns: [ { offset: 25, repeat: 70, symbol: L.Symbol.arrowHead({pixelSize: 14, pathOptions: {fillOpacity: 1, weight: 0, color: '#ef4444'}}) } ]
                                    }).addTo(mapLayers.evacRoute);
                                }
                            });
                            mapLayers.evacRoute.addLayer(routeLayer);
                        } else if (mapLayers[key]) {
                            mapLayers[key].addData(data);
                        }
                    }
                } catch(e) { console.error(`Gagal load GeoJSON ${key}:`, e); }
            }));

            // 2. Fetch Marker dari Apps Script (format: flat object, no status/data wrapper)
            try {
                const resp = await fetch(APPS_SCRIPT_URL + '?tab=ALL', { redirect: 'follow' });
                const result = await resp.json();

                // New format: flat object { Beranda: {...}, Bangunan: [...], Evakuasi: [...], ... }
                // Old format: { status: 'success', data: { ... } }
                const flatData = result.status === 'success' ? result.data : result;

                const bgn = flatData['bangunan'] || flatData['Bangunan'] || [];

                // Inisialisasi checklist kategori
                const kategoriList = ['Ibadah', 'Pendidikan', 'Pemerintahan', 'Kesehatan', 'Fasilitas Umum', 'Infrastruktur', 'Wisata', 'Default'];
                poiMarkers = [];

                bgn.forEach(b => {
                    if(b.Latitude && b.Longitude) {
                        const lat = parseFloat(String(b.Latitude).replace(',', '.'));
                        const lng = parseFloat(String(b.Longitude).replace(',', '.'));
                        if(!isNaN(lat) && !isNaN(lng)) {
                            const kategori = b.Kategori || 'Default';
                            const cb = document.querySelector(`.kategori-checkbox[value="${kategori}"]`);
                            const marker = L.marker([lat, lng], { icon: getCustomIcon(kategori, false) });
                            marker.bindPopup(`<h4>${b.Nama || '-'}</h4><p>Dusun: ${b.Dusun || '-'}</p><p>Kategori: ${kategori}</p>`);
                            mapLayers.poiBangunan.addLayer(marker);
                            poiMarkers.push({ marker: marker, kategori: kategori, cb: cb });
                        }
                    }
                });

                // Event listener: centang/klik per kategori
                kategoriList.forEach(kat => {
                    const cb = document.querySelector(`.kategori-checkbox[value="${kat}"]`);
                    if (cb) {
                        cb.addEventListener('change', function() {
                            filterKategori(kat);
                        });
                    }
                });

                // Event listener: cek semua / kosongkan
                const checkAllBtn = document.getElementById('check-all-btn');
                if (checkAllBtn) {
                    checkAllBtn.addEventListener('click', function() {
                        const allChecked = Array.from(document.querySelectorAll('.kategori-checkbox')).every(cb => cb.checked);
                        checkAllKategori(!allChecked);
                    });
                }

                const evk = flatData['evakuasi'] || flatData['Evakuasi'] || [];
                evk.forEach(e => {
                    if(e.Latitude && e.Longitude) {
                        const lat = parseFloat(String(e.Latitude).replace(',', '.'));
                        const lng = parseFloat(String(e.Longitude).replace(',', '.'));
                        if(!isNaN(lat) && !isNaN(lng)) {
                            const marker = L.marker([lat, lng], { icon: getCustomIcon('Evakuasi', true) });
                            marker.bindPopup(`<h4>${e.Nama || '-'}</h4><p>Kapasitas: ${e.Kapasitas || '-'} Jiwa</p><p>${e.Keterangan || '-'}</p>`);
                            mapLayers.poiEvakuasi.addLayer(marker);
                        }
                    }
                });
            } catch(e) { console.error('Gagal merender titik dari Sheets:', e); }
        }

        // --- Berita ---
        // filterNews, showDetail, hideDetail sekarang ditangani langsung
        // oleh JavaScript di halaman Berita.html (menggunakan Blogger Feed)


        // ==========================================
        // E. INISIALISASI
        // ==========================================
        document.addEventListener('DOMContentLoaded', () => {
            const currentPath = window.location.pathname;
            document.querySelectorAll('.nav-link, .mobile-nav-link').forEach(link => {
                if (currentPath === new URL(link.href, window.location.origin).pathname) link.classList.add('active');
            });

            const bloggerContent = document.querySelector('.post-body, .entry-content, .widget.Blog');
            const destination = document.getElementById('teleport-destination');
            if (bloggerContent && destination) {
                destination.innerHTML = bloggerContent.innerHTML;
                bloggerContent.innerHTML = ''; // Hapus sisa asli
            }

            const slider = document.getElementById('wisata-slider');
            const scrollLeftBtn = document.getElementById('scroll-left');
            const scrollRightBtn = document.getElementById('scroll-right');
            if (slider && scrollLeftBtn && scrollRightBtn) {
                scrollLeftBtn.addEventListener('click', () => { slider.scrollBy({ left: -440, behavior: 'smooth' }); });
                scrollRightBtn.addEventListener('click', () => { slider.scrollBy({ left: 440, behavior: 'smooth' }); });
            }

            renderData();
if (document.getElementById('map-loading')) {
                setTimeout(() => window.initMap(), 500);
            }
        });
    //
